Theorem AFUZZ_closed : AFUZZ.
Proof. intros HCEIL H HH H5 H5x H6 H6b H7 H8 ATR. exact (afuzz_closed H HH H5 H5x H6 H6b H7 H8 ATR). Qed.

Theorem ACOST_closed : ACOST.
Proof.
  apply ACOST_of_bound. intros HCEIL p. unfold afuzz_cost, AFUZZ_COST_MAX. cbn [as_Cm as_Cf KHp]. unfold ICm, ICf.
  change (13 * 2 ^ 26 + 600000000 <=? 64512) with false. cbv iota. lia.
Qed.
